#define PIPE_WIDTH 1.0

vec3 rot(vec3 p, vec3 ax, float t) {
    return mix(dot(ax, p) * ax, p, cos(t)) + cross(ax, p) * sin(t);
}

float smin( float a, float b, float k )
{
    k *= 4.0;
    float h = max( k-abs(a-b), 0.0 )/k;
    return min(a,b) - h*h*k*(1.0/4.0);
}

float smin(float a, float b) {
    return smin(a, b, 0.05);
}


float modd(float v, float m) {
    v = v + m / 2.;
    return v - (m * floor(v/m)) - m/2.;
}

vec3 vmodxy(vec3 v, float m) {
    return vec3(modd(v.x, m), modd(v.y, m), v.z);
}
vec3 vmodxyz(vec3 v, float m) {
    return vec3(modd(v.x, m), modd(v.y, m), modd(v.z, m));
}

