//box sdf
float box(vec3 p, vec3 b){
    vec3 q = abs(p)-b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float bump(float x) {
    if (abs(x) > 1.) {
        return 0.;
    }
    return exp(-1. / (1. - x*x));
}

const int SEGMENTS_SHOWN = 30;

vec2 map(vec3 p, vec3 rayDir, bool useDir){
    float simTime = mod(float(iFrame) / 60., SIM_LEN);
    vec4 status1 = loadValue(ivec2(0, 0));
    float lastTime = status1.x;
    int segmentCount = int(status1.y);
    int numSimulation = int(status1.z);

    vec2 result = vec2(50.0, 0.0);
    if (segmentCount <= SEGMENTS_SHOWN) result.x = length(p) - 1.5;
    vec3 p0 = p;

    for (int i = segmentCount - SEGMENTS_SHOWN; i < segmentCount; i++) {
        vec4 startPosition = loadValueSeq(i * 3);
        vec4 direction = loadValueSeq(i * 3 + 1);

        vec3 pos = startPosition.xyz, dir = direction.xyz;
        vec4 other = loadValueSeq(i * 3 + 2);
        float len = clamp(simTime * VEL - other.y, 0., other.x);
        //float len = other.x;

        float l = clamp(dot(dir, p - pos), 0., len);
        // closest point on the segment
        vec3 closest = pos + l * dir;

        float dist = length(p - closest) - PIPE_WIDTH;


        //if ((!useDir || dot(rayDir, p - closest) < 0.)) {
            if (dist < result.x) {
                float total = other.y + l;
                float freq = 30.;
                result.y = bump(0.2 * (mod(total - simTime * VEL * 2. + freq, freq * 2.) - freq));
            }
            result.x = min(result.x, dist);
        //}
    }
    return result;
}

vec2 map(vec3 p){
    return map(p, vec3(0.), false);
}

vec3 normal(vec3 p) {
    float s = 0.01;
    vec2 off=vec2(s,0);
    return normalize(
    vec3(map(p + off.xyy).x, map(p + off.yxy).x, map(p + off.yyx).x)
    -vec3(map(p - off.xyy).x, map(p - off.yxy).x, map(p - off.yyx).x));
}




// Compute the refraction of a ray entering in direction dir into a medium with normal vector normal.
// Outwards facing normal vector, for leaving this needs to be called with -normal.
// (Hopefully identical to the builtin refract in shadertoy)
// https://physics.stackexchange.com/questions/435512/snells-law-in-vector-form
vec3 refract_(vec3 dir, vec3 normal, float refractRatio) {
    float ndotr = -dot(normal, dir);
    float sinSqrAngleOfRefraction = refractRatio*refractRatio * (1.0 - ndotr * ndotr);
    if (sinSqrAngleOfRefraction > 1.) return vec3(0.); // Total Reflection, no refraction occurs

    vec3 refractDir = (ndotr * refractRatio - sqrt(1.0 - sinSqrAngleOfRefraction)) * normal + refractRatio * dir;
    return refractDir;
}


// Portion of light that is reflected at the boundary of two media
// Value is in the range [0, 1] where 0 = no light reflected, 1 = all light reflected
// http://graphics.stanford.edu/courses/cs148-10-summer/docs/2006--degreve--reflection_refraction.pdf
// via https://www.youtube.com/watch?v=kOkfC5fLfgE
float calculateReflectance(vec3 inDir, vec3 normal, float iorA, float iorB) {
    float refractRatio = iorA / iorB;
    float cosIn = -dot(inDir, normal);
    float sinSqrRefract = refractRatio * refractRatio * (1. - cosIn * cosIn);

    // Check for full reflection
    if (sinSqrRefract >= 1.) {return 1.;}

    // Calculate Reflectance for perpendicular and parallel polarizations
    float cosRefract = sqrt(1. - sinSqrRefract);
    float sqrtRayPerp = (iorA * cosIn - iorB * cosRefract) / (iorA * cosIn + iorB * cosRefract);
    float sqrtRayParallel = (iorB * cosIn - iorA * cosRefract) / (iorB * cosIn + iorA * cosRefract);

    // Return average for unpolarized light
    return (sqrtRayPerp * sqrtRayPerp + sqrtRayParallel * sqrtRayParallel) / 2.;
}



#define STEPS 96.0
#define MDIST 100.0

void render( out vec4 fragColor, in vec2 fragCoord )
{
    // Camera
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.y;
    float angle = (float(iFrame) / 60.) * 0.5;
    // short: ro
    vec3 cameraPosition = loadValue(ivec2(3, 0)).xyz;
    // camera interpolation not smooth at the moment, use fixed camera position instead
    cameraPosition = vec3(0., 0., 0.);
    vec3 rayOrigin = vec3(40.0 * cos(angle), 6.0, -40.0 * sin(angle)) + cameraPosition;
    // short: lk, rt
    vec3 cameraTarget = vec3(0,0,0.0) + cameraPosition;
    vec3 cameraDirection = normalize(cameraTarget - rayOrigin);
    vec3 up = vec3(0,1,0);
    vec3 cameraU = normalize(cross(up, cameraDirection));
    vec3 cameraV = cross(cameraDirection, cameraU);
    vec3 rayDirection = cameraDirection * 0.9 + uv.x * cameraU + uv.y * cameraV;
    bool hit = false;

    vec4 color = loadValue(ivec2(1, 0));

    // Raymarching variables
    float rayDist;
    vec3 p = rayOrigin;
    vec2 d;
    vec4 col = vec4(0.);
    vec3 normal1;
    bool inside;
    bool entered = false;
    bool left = false;

    // Raymarch loop
    for(float i = 0.0; i<STEPS; i++){
        // Raymarching Begin        
        d = map(p, rayDirection, false);
        bool previousInside = inside;
        inside = d.x <= 0.0;
        entered = !previousInside && inside;
        left = previousInside && !inside;

        float rnd = mod(rayDist * 10000., 1.);


        // Transparent material coloring
        if (inside) {
            // inside material, effect gets stronger the longer we are inside
            //if (d.x > -0.5) {
                col.xyzw += color * (abs(d.x)) / 15.0 * (1. - col.w);
            //}
            // faint moving dots inside the pipe
            col.xyzw += d.y * vec4(.9, 0.9, 0.3, 1.) * (abs(d.x)) / 20.0 * (1. - col.w);
        } else {
            // glow
            col.xyzw += color / 100. * (1. - col.w);
        }
        if (entered) {
            // constant effect on entering material
            col.xyzw += color / 10.0 * (1. - col.w);
        }



        // Transparent material Refraction
        if (entered || left) {
            normal1 = normal(p);
            float mu = 0.9;
            float iorA = entered ? mu : 1.;
            float iorB = entered ? 1. : mu;
            if (left) { mu = 1. / mu; }

            vec3 reflected = reflect(rayDirection, normal1);
            float s = entered ? 1. : -1.;
            vec3 refracted = refract_(rayDirection, s * normal1, mu);
            float reflectance = calculateReflectance(rayDirection, s * normal1, iorA, iorB);;
            if (entered) {
                rayDirection = refracted;
            } else {
                // check for total reflection
                if (length(refracted) < 0.1 || reflectance > 0.5 ) {
                    rayDirection = reflected;
                } else {
                    rayDirection = refracted;
                }
            }
            //fragColor = vec4(rayDirection, 1.0);return;
        }

        if (col.w >= 0.9) {
            break;
        }

        // Raymarching End Step

        // if very close, step in to avoid slow convergence
        if(abs(d.x) < 0.01) {
            d.x = 0.02;
        }

        float stepLength = abs(d.x) * (0.7 + rnd * 0.15);
        //float stepLength = abs(d.x) * 0.825;
        rayDist += stepLength;
        if(rayDist>MDIST) {
            col.w = 1.0;
            break;
        }
        p += rayDirection * stepLength;
    }


    fragColor = col;
}


