// Compute Pipe Values and store for convenient iteration

// Memory Layout. ivec2 -> vec4 mapping
// (0, 0): (unused, segmentCount, numSimulation, unused)
// (1, 0): pipe color
// (2, 0): white
// (3, 0): proposed camera lookat
// (0, 1) - (2, 1): pipeStartPosition, pipeDirection, (pipeSegmentLength, totalLength, 0., 0.)
// sequentially layed out for all pipe segments, width 32.


// Memory functions from https://www.shadertoy.com/view/Ms3XWN
void storeValue( in ivec2 re, in vec4 va, inout vec4 fragColor, in ivec2 ifragCoord )
{
    fragColor = ( re.x==ifragCoord.x && re.y==ifragCoord.y ) ? va : fragColor;
}

vec4 loadValue( in ivec2 re )
{
    return texelFetch( iChannel0, re, 0 );
}

ivec2 seqPos(int pos) {
    return ivec2((pos) % 32, pos / 32 + 1);
}

void storeValueSeq( int pos, in vec4 va, inout vec4 fragColor, in ivec2 iFragCoord ) {
    storeValue(seqPos(pos), va, fragColor, iFragCoord);
}

vec4 loadValueSeq( int pos )
{
    return texelFetch( iChannel0, seqPos(pos), 0 );
}



void init(int numSimulation, inout vec4 fragColor, in ivec2 iFragCoord) 
{
    vec4 initialStatus1 = vec4(0., 1., float(numSimulation), 0.);
    storeValue(ivec2(0, 0), initialStatus1, fragColor, iFragCoord);
    storeValue(ivec2(2, 0), vec4(1.0), fragColor, iFragCoord);

    float seed = hash11(float(iFrame + 5) * 10.6932);
    vec3 col = vec3(0.5) + hash31(float(numSimulation + 7) * 1.3214);
    vec4 colVec4 = vec4(col, 1.0);
    storeValue(ivec2(1, 0), colVec4, fragColor, iFragCoord);

    vec4 initialPos = vec4(0., 0., 0., 1.);
    storeValue(ivec2(0, 1), initialPos, fragColor, iFragCoord);
    vec4 initialDir = vec4(1., 0., 0., 0.);
    storeValue(ivec2(1, 1), initialDir, fragColor, iFragCoord);
    vec4 initialStatus = vec4(5., 0., 0., 0.);
    storeValue(ivec2(2, 1), initialStatus, fragColor, iFragCoord);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 iFragCoord = ivec2( fragCoord-0.5 );
    // Don't compute outside of the data area
    if( iFragCoord.x > 32 || iFragCoord.y>32 ) discard;

    // First frame Init.
    if (iFrame < 2) {
        init(0, fragColor, iFragCoord);
        return;
    }

    float simTime = mod((float(iFrame) / 60.), SIM_LEN);
    vec4 status1 = loadValue(ivec2(0, 0));
    float lastTime = status1.x;
    int segmentCount = int(status1.y);
    int numSimulation = int(status1.z);

    // Reset after the simulation has run long enough
    if (int((float(iFrame) / 60.) / SIM_LEN) > numSimulation) {
        numSimulation++;
        init(numSimulation, fragColor, iFragCoord);
        return;
    }

    // This doesn't need to run every frame, also fixes some jittering issues that I was too lazy to debug.
    if ((iFrame & 1) != 1) { fragColor = loadValue(iFragCoord); return; }

    // Only compute if we're at a position that will actually be updated

    if (iFragCoord != seqPos(segmentCount * 3) 
        && iFragCoord != seqPos(segmentCount * 3 + 1) 
        && iFragCoord != seqPos(segmentCount * 3 + 2)
        && iFragCoord != ivec2(0, 0)
        && iFragCoord != ivec2(3, 0)
    ) {
        discard;
    }

    // Compute the next pipe segment
    float size = 10.0;

    vec4 startPosition = loadValueSeq(segmentCount * 3 - 3);
    vec4 direction = loadValueSeq(segmentCount * 3 - 2);
    vec4 other = loadValueSeq(segmentCount * 3 - 1);

    float len = other.x;
    float startTotalLen = other.y;

    vec3 cameraPosition = loadValue(ivec2(3, 0)).xyz;
    float camWeight = 0.05;
    float foo = simTime * VEL - startTotalLen;
    vec3 target = startPosition.xyz + direction.xyz * (foo);
    cameraPosition = (1. - camWeight) * cameraPosition + camWeight * target;
    //cameraPosition = startPosition.xyz;
    storeValue(ivec2(3, 0), vec4(cameraPosition.x, cameraPosition.y, cameraPosition.z, 1.), fragColor, iFragCoord);

    if (foo >= len - 2.) {
        vec4 newStartPosition = len * direction + startPosition;
        vec3 newDir = vec3(0.);
        int dirID = 0;
        if (abs(direction.y) > 0.1) {
            dirID = 1;
        }
        if (abs(direction.z) > 0.1) {
            dirID = 2;
        }
        float hash = hash13(startPosition.xyz + vec3(float(numSimulation)));
        int rnd = int(hash * 4.);
        int newID = (dirID + 1 + ((rnd & 2) >> 1) ) % 3;
        if (newID == 0) {
            newDir.x = 1.0;
        } else if (newID == 1) {
            newDir.y = 1.0;
        } else {
            newDir.z = 1.0;
        }
        int sgn = (rnd & 1);
        if (sgn == 0) { newDir *= -1.0; }
        if (dot(newDir, newStartPosition.xyz) > 10.0) { newDir *= -1.; }
        float newLen = 2.0 + mod(hash, 0.25) * 4.0 * 20.0;
        float newTotalLen = len + startTotalLen;
        vec4 newOther = vec4(newLen, newTotalLen, 0., 0.);

        storeValueSeq(segmentCount*3, newStartPosition, fragColor, iFragCoord); 
        storeValueSeq(segmentCount*3 + 1, vec4(newDir.x, newDir.y, newDir.z, 0.0), fragColor, iFragCoord); 
        //storeValueSeq(segmentCount*3 + 1, vec4(0., 1., 0., 0.0), fragColor, iFragCoord); 
        storeValueSeq(segmentCount*3 + 2, newOther, fragColor, iFragCoord); 
        if (iFragCoord == ivec2(0, 0)) { segmentCount++; }
    }
    // Save the current status
    storeValue(ivec2(0, 0), vec4(simTime, segmentCount, numSimulation, 1.), fragColor, iFragCoord);
}

#define VEL 50.0
#define SIM_LEN 15.0

// https://www.shadertoy.com/view/4djSRW
float hash11(float p)
{
    p = fract(p * .1031);
    p *= p + 33.33;
    p *= p + p;
    return fract(p);
}

vec3 hash31(float p)
{
   vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
   p3 += dot(p3, p3.yzx+33.33);
   return fract((p3.xxy+p3.yzz)*p3.zyx); 
}

float hash13(vec3 p3)
{
	p3  = fract(p3 * .1031);
    p3 += dot(p3, p3.zyx + 31.32);
    return fract((p3.x + p3.y) * p3.z);
}
